class MyWallets extends ConsumerStatefulWidget {
  const MyWallets({super.key});

  @override
  ConsumerState<MyWallets> createState() => _MyWalletsState();
}

class _MyWalletsState extends ConsumerState<MyWallets> {
  @override
  Widget build(BuildContext context) {
    final showFavorites = ref.watch(
      prefsChangeNotifierProvider.select((value) => value.showFavoriteWallets),
    );

    return Padding(
      padding: const EdgeInsets.only(top: 24, left: 14, right: 14, bottom: 0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (showFavorites)
            const Padding(
              padding: EdgeInsets.symmetric(horizontal: 10),
              child: DesktopFavoriteWallets(),
            ),
          Padding(
            padding: const EdgeInsets.all(10),
            child: Row(
              children: [
                Text(
                  "All wallets",
                  style: STextStyles.desktopTextExtraSmall(context).copyWith(
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .textFieldActiveSearchIconRight,
                  ),
                ),
                const Spacer(),
                CustomTextButton(
                  text: "Add new wallet",
                  onTap: () => pushAddWallet(context, ref, rootNavigator: true),
                ),
              ],
            ),
          ),
          const SizedBox(height: 20),
          Expanded(
            // One list when every coin is a network of the same one (PIVX
            // and its test network), as on mobile.
            child: AppConfig.coins.map((e) => e.mainNetId).toSet().length == 1
                ? WalletsOverview(
                    coin: AppConfig.coins.first,
                    allNetworks: true,
                    navigatorState: Navigator.of(context),
                    overrideSimpleWalletCardPopPreviousValueWith: false,
                  )
                : const WalletSummaryTable(),
          ),
        ],
      ),
    );
  }
}
